# Playwright 基础与实战

## 核心概念

Playwright 是一个强大的 E2E 测试框架，支持多个浏览器和平台。它由微软开发，能驱动 Chromium、Firefox 和 WebKit 三大浏览器引擎，提供自动等待、网络拦截、多页面/多上下文等高级能力。

```mermaid
graph TD
    A[Playwright 测试] --> B[浏览器引擎]
    B --> C[Chromium]
    B --> D[Firefox]
    B --> E[WebKit]
    A --> F[测试能力]
    F --> G[Locators 定位]
    F --> H[Auto-wait 自动等待]
    F --> I[Network 网络拦截]
    F --> J[Trace 追踪调试]
```

| 特性     | Playwright            | Cypress        | 说明                |
| -------- | --------------------- | -------------- | ------------------- |
| 多浏览器 | ✅ Chromium/FF/WebKit | ❌ 仅 Chromium | Playwright 覆盖更广 |
| 多标签页 | ✅ 原生支持           | ❌ 不支持      | 复杂流程必需        |
| iframe   | ✅ 原生支持           | 部分支持       | 第三方集成常见      |
| 并行执行 | ✅ 进程级并行         | 有限           | 大规模测试提速      |
| 自动等待 | ✅ 内置               | ✅ 内置        | 两者都有            |
| 调试体验 | Trace Viewer          | Time Travel    | 各有优势            |

## 安装与配置

```bash
npm init playwright@latest
```

```typescript
// playwright.config.ts
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: 'html',
  use: {
    baseURL: 'http://localhost:3000',
    trace: 'on-first-retry',
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
    {
      name: 'firefox',
      use: { ...devices['Desktop Firefox'] },
    },
    {
      name: 'webkit',
      use: { ...devices['Desktop Safari'] },
    },
  ],
  webServer: {
    command: 'npm run dev',
    url: 'http://localhost:3000',
    reuseExistingServer: !process.env.CI,
  },
});
```

## 基础测试

```typescript
import { test, expect } from '@playwright/test';

test('homepage has title', async ({ page }) => {
  await page.goto('/');
  await expect(page).toHaveTitle(/My App/);
});

test('login flow', async ({ page }) => {
  await page.goto('/login');

  await page.fill('input[name="email"]', 'alice@example.com');
  await page.fill('input[name="password"]', 'password123');
  await page.click('button[type="submit"]');

  await expect(page).toHaveURL('/dashboard');
  await expect(page.locator('h1')).toContainText('Welcome');
});
```

## Locators

```typescript
import { test, expect } from '@playwright/test';

test('locators', async ({ page }) => {
  await page.goto('/');

  // 通过角色
  await page.getByRole('button', { name: 'Submit' }).click();

  // 通过文本
  await page.getByText('Click me').click();

  // 通过标签
  await page.getByLabel('Email').fill('alice@example.com');

  // 通过 placeholder
  await page.getByPlaceholder('Search').fill('query');

  // 通过 test id
  await page.getByTestId('submit-button').click();
});
```

## 断言

```typescript
import { test, expect } from '@playwright/test';

test('assertions', async ({ page }) => {
  await page.goto('/');

  // URL
  await expect(page).toHaveURL('/');
  await expect(page).toHaveURL(/dashboard/);

  // 标题
  await expect(page).toHaveTitle(/My App/);

  // 元素可见
  await expect(page.locator('h1')).toBeVisible();
  await expect(page.locator('.hidden')).toBeHidden();

  // 文本
  await expect(page.locator('h1')).toContainText('Welcome');
  await expect(page.locator('h1')).toHaveText('Welcome, Alice!');

  // 输入值
  await expect(page.locator('input[name="email"]')).toHaveValue('alice@example.com');

  // 计数
  await expect(page.locator('.item')).toHaveCount(5);
});
```

## 交互

```typescript
import { test, expect } from '@playwright/test';

test('interactions', async ({ page }) => {
  await page.goto('/');

  // 点击
  await page.click('button');
  await page.dblclick('button');

  // 输入
  await page.fill('input', 'text');
  await page.type('input', 'text', { delay: 100 });

  // 选择
  await page.selectOption('select', 'option-value');
  await page.selectOption('select', ['option1', 'option2']);

  // 勾选
  await page.check('input[type="checkbox"]');
  await page.uncheck('input[type="checkbox"]');

  // 悬停
  await page.hover('button');

  // 拖拽
  await page.dragAndDrop('.source', '.target');

  // 文件上传
  await page.setInputFiles('input[type="file"]', 'path/to/file.txt');
});
```

## 导航

```typescript
import { test, expect } from '@playwright/test';

test('navigation', async ({ page }) => {
  await page.goto('/');

  await page.goBack();
  await page.goForward();
  await page.reload();
});
```

## 等待

```typescript
import { test, expect } from '@playwright/test';

test('waiting', async ({ page }) => {
  await page.goto('/');

  // 等待导航
  await page.waitForURL('/dashboard');

  // 等待元素
  await page.waitForSelector('.loaded');

  // 等待网络
  await page.waitForResponse('/api/data');

  // 等待函数
  await page.waitForFunction(() => document.readyState === 'complete');
});
```

## Page Object Model

```typescript
// pages/LoginPage.ts
import { type Page, type Locator } from '@playwright/test';

export class LoginPage {
  readonly page: Page;
  readonly emailInput: Locator;
  readonly passwordInput: Locator;
  readonly submitButton: Locator;
  readonly errorMessage: Locator;

  constructor(page: Page) {
    this.page = page;
    this.emailInput = page.getByLabel('Email');
    this.passwordInput = page.getByLabel('Password');
    this.submitButton = page.getByRole('button', { name: 'Login' });
    this.errorMessage = page.locator('.error');
  }

  async goto() {
    await this.page.goto('/login');
  }

  async login(email: string, password: string) {
    await this.emailInput.fill(email);
    await this.passwordInput.fill(password);
    await this.submitButton.click();
  }
}

// tests/login.spec.ts
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';

test('login with POM', async ({ page }) => {
  const loginPage = new LoginPage(page);
  await loginPage.goto();
  await loginPage.login('alice@example.com', 'password123');
  await expect(page).toHaveURL('/dashboard');
});
```

## 小结

```mermaid
mindmap
  root((Playwright))
    核心能力
      多浏览器
      自动等待
      网络拦截
      Trace 调试
    Locator
      ByRole
      ByText
      ByLabel
      ByTestId
    断言
      toBeVisible
      toHaveText
      toHaveURL
      toHaveCount
    设计模式
      Page Object Model
      封装页面操作
      复用测试逻辑
```

- 支持 Chromium、Firefox、WebKit 三大浏览器引擎
- 使用语义化 Locator 定位元素，优先 ByRole
- Page Object Model 是组织 E2E 测试的推荐模式
- 自动等待和重试机制减少测试不稳定性
